      { title: "修复分享卡片金额对齐", desc: "按反馈修复资产分析-账户资产-分享当日盈亏复制出的图片中金额元素错位：持仓市值右侧币种由小字改为与金额同字号并基线对齐；当日持仓盈亏金额右侧币种改为行内基线布局（底部对齐，不再浮在数字上方）；持仓市值前的圆形徽标改为单层居中，消除复制图片中的上下错位。", kind: "fix" }
