    desc: "在搜索框下方加了一条「我的卡」总览：我的卡 N 张、各类型张数（按数量排）、额度合计 ≈ ¥xx（沿用按币种合计 + 汇率折算的口径，没有录入时显示「未录入（打开卡片可录入金额）」）。\n第二行保留按币种的明细胶囊（CNY 12,000 ×3）与「无汇率未折算」提示；原来那条只按币种的「金额汇总」合并进这条总览，信息不再重复。\n顺带修一处不一致：筛选区的计数原来一律按全量 436 张统计，在「我的卡」模式下会出现「我的卡只有 3 张、类型却写着借记卡 251」这种矛盾；现在所有计数都跟随当前模式，银行下拉也只列当前作用域里出现过的银行。",
    kind: "feature"
