    desc: "线上（群晖）升级到非 root 镜像后出现过容器无限重启：DATA_DIR / UPLOADS_DIR 是宿主机 bind mount，属主不是容器内的 uid 1000（node 用户），启动脚本写公开缓存种子时报 EACCES，而 entrypoint 带 set -e 会直接退出，被 restart: unless-stopped 反复拉起。\n现在 entrypoint 启动前先自检两个挂载目录的写权限：数据目录不可写时打印明确的中文提示（含 chown -R 1000:1000 data uploads 这行命令）后再退出；上传目录不可写只告警，服务照常启动；公开缓存种子合并失败一律只告警。\n部署文档补上「挂载目录属主必须是 1000:1000」的前置步骤，以及「升级后容器无限重启、日志只有 EACCES」的排查章节。\n部署一致性审计改为校验「镜像内路径必须被启动脚本引用」这一不变式，并补了一条回归用例同时覆盖「数据目录不可写必须报错退出」与「种子失败不阻塞启动」。",
