    desc: "两件事：一是倒影还是发虚像磨砂玻璃，根因是程序化粗糙度贴图给了 0.28-0.62 的粗糙度，反射固定被模糊掉 0.3-0.7 个 mip 级别。现在粗糙度收到 0.1-0.26、粗糙度对 mip 的影响系数从 1.1 降到 0.5、底色混合从 0.3 提到 0.46（浅色主题 0.06 → 0.32、反射强度 0.34 → 0.6）、法线扰动 0.25 → 0.18，车身的 VELO 反字现在能清楚读出来。\\n二是转动镜头时倒影会抖：之前为了省绘制调用把地面反射改成「隔帧更新」，反射比画面慢一帧，转动时就成了抖动。现在改成按运动判断——相机或车只要动过就逐帧更新，完全静止时才隔帧更新，既没有抖动也保留静止时的省电。\\n同时把音乐开关的图标从单音符换成双音符（播放实心、暂停描边），配色仍跟随深浅色主题。",
